package org.cloudburstmc.protocol.bedrock.codec.v924.serializer;
import io.netty.buffer.ByteBuf; import org.cloudburstmc.protocol.bedrock.codec.BedrockCodecHelper; import org.cloudburstmc.protocol.bedrock.codec.v291.serializer.BookEditSerializer_v291; import org.cloudburstmc.protocol.bedrock.packet.BookEditPacket; import org.cloudburstmc.protocol.common.util.TextConverter; import org.cloudburstmc.protocol.common.util.VarInts;
public class BookEditSerializer_v924 extends BookEditSerializer_v291 { public static final BookEditSerializer_v924 INSTANCE=new BookEditSerializer_v924();
@Override public void serialize(ByteBuf b,BedrockCodecHelper h,BookEditPacket p){VarInts.writeInt(b,p.getInventorySlot());VarInts.writeUnsignedInt(b,p.getAction().ordinal());TextConverter c=h.getTextConverter();switch(p.getAction()){case REPLACE_PAGE:case ADD_PAGE:VarInts.writeInt(b,p.getPageNumber());h.writeString(b,c.serialize(p.getText(CharSequence.class)));h.writeString(b,p.getPhotoName());break;case DELETE_PAGE:VarInts.writeInt(b,p.getPageNumber());break;case SWAP_PAGES:VarInts.writeInt(b,p.getPageNumber());VarInts.writeInt(b,p.getSecondaryPageNumber());break;case SIGN_BOOK:h.writeString(b,c.serialize(p.getTitle(CharSequence.class)));h.writeString(b,c.serialize(p.getAuthor(CharSequence.class)));h.writeString(b,p.getXuid());break;}}
@Override public void deserialize(ByteBuf b,BedrockCodecHelper h,BookEditPacket p){p.setInventorySlot(VarInts.readInt(b));p.setAction(types.get(VarInts.readUnsignedInt(b)));TextConverter c=h.getTextConverter();switch(p.getAction()){case REPLACE_PAGE:case ADD_PAGE:p.setPageNumber(VarInts.readInt(b));p.setText(c.deserialize(h.readString(b)));p.setPhotoName(h.readString(b));break;case DELETE_PAGE:p.setPageNumber(VarInts.readInt(b));break;case SWAP_PAGES:p.setPageNumber(VarInts.readInt(b));p.setSecondaryPageNumber(VarInts.readInt(b));break;case SIGN_BOOK:p.setTitle(c.deserialize(h.readString(b)));p.setAuthor(c.deserialize(h.readString(b)));p.setXuid(h.readString(b));break;}}}
